handleEvent(event) {
  switch (event.type) {
    case "submit":
      this.#onSubmit(event);
      break;
    case "input":
      this.#onInput(event);
      break;
    case "reset":
      this.reset();
      this.focus();
      break;
    case "keydown":
      if (event.key === "Escape" && this.#input.value) {
        this.reset();
        event.preventDefault();
        event.stopPropagation();
      }
      break;
  }
}

focus() {
  this.#input.focus();
  if (this.#input.value) {
    this.#input.select();
  }
}

/**
 * Reset the search bar to its empty state.
 */
reset() {
  if (this.#input.value == "") {
    return;
  }

  this.#input.value = "";
  clearTimeout(this.#inputTimeout);
  this.#inputTimeout = undefined;
  this.#fireAutocomplete();
}
